irj a honlapomnak egy olyan designet mint ez a honlap; 

css:
@font-face {
	font-family: Neue Haas Grotesk Display Pro;
	src: url("/fonts/NeueHaasGrotesk/NeueHaasDisplay-Black.woff2") format("woff2"), url("/fonts/NeueHaasGrotesk/NeueHaasDisplay-Black.woff") format("woff");
	font-weight: 900;
	font-style: normal;
	font-display: swap;
}

@font-face {
	font-family: Neue Haas Grotesk Display Pro;
	src: url("/fonts/NeueHaasGrotesk/NeueHaasDisplay-Bold.woff2") format("woff2"), url("/fonts/NeueHaasGrotesk/NeueHaasDisplay-Bold.woff") format("woff");
	font-weight: 700;
	font-style: normal;
	font-display: swap;
}

@font-face {
	font-family: Neue Haas Grotesk Display Pro;
	src: url("/fonts/NeueHaasGrotesk/NeueHaasDisplay-Roman.woff2") format("woff2"), url("/fonts/NeueHaasGrotesk/NeueHaasDisplay-Roman.woff") format("woff");
	font-weight: 500;
	font-style: normal;
	font-display: swap;
}

@font-face {
	font-family: Neue Haas Grotesk Display Pro;
	src: url("/fonts/NeueHaasGrotesk/NeueHaasDisplay-Light.woff2") format("woff2"), url("/fonts/NeueHaasGrotesk/NeueHaasDisplay-Light.woff") format("woff");
	font-weight: 300;
	font-style: normal;
	font-display: swap;
}

@font-face {
	font-family: Inter;
	src: url("/fonts/Inter/Inter-Bold.woff2") format("woff2"), url("/fonts/Inter/Inter-Bold.woff") format("woff");
	font-weight: 700;
	font-style: normal;
	font-display: swap;
}

@font-face {
	font-family: Inter;
	src: url("/fonts/Inter/Inter-SemiBold.woff2") format("woff2"), url("/fonts/Inter/Inter-SemiBold.woff") format("woff");
	font-weight: 500;
	font-style: normal;
	font-display: swap;
}

@font-face {
	font-family: Inter;
	src: url("/fonts/Inter/Inter-Regular.woff2") format("woff2"), url("/fonts/Inter/Inter-Regular.woff") format("woff");
	font-weight: 400;
	font-style: normal;
	font-display: swap;
}

@font-face {
	font-family: Inter;
	src: url("/fonts/Inter/Inter-Light.woff2") format("woff2"), url("/fonts/Inter/Inter-Light.woff") format("woff");
	font-weight: 300;
	font-style: normal;
	font-display: swap;
}

*,
::after,
::before {
	margin: 0;
	padding: 0;
	box-sizing: border-box;
	border: 0 solid #e5e7eb;
}

::after,
::before {
	content: "";
}

html {
	line-height: 1.5;
	-webkit-text-size-adjust: 100%;
	-moz-tab-size: 4;
	tab-size: 4;
	font-family: Inter, ui-sans-serif, system-ui, sans-serif;
	font-feature-settings: normal;
	font-variation-settings: normal;
	-webkit-tap-highlight-color: transparent;
}

body {
	margin: 0;
	line-height: inherit;
	width: 100%;
	overflow-x: hidden;
	background-color: #000000;
	color: #ffffff;
	-webkit-font-smoothing: antialiased;
	-moz-osx-font-smoothing: grayscale;
	font-smooth: never;
}

h1,
h2,
h3,
h4,
h5,
h6 {
	font-size: inherit;
	font-weight: inherit;
}

a {
	color: inherit;
	text-decoration: inherit;
}

b,
strong {
	font-weight: bolder;
}

code,
kbd,
pre,
samp {
	font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, Liberation Mono, Courier New, monospace;
	font-feature-settings: normal;
	font-variation-settings: normal;
	font-size: 1em;
}

button,
input,
optgroup,
select,
textarea {
	font-family: inherit;
	font-feature-settings: inherit;
	font-variation-settings: inherit;
	font-size: 100%;
	font-weight: inherit;
	line-height: inherit;
	letter-spacing: inherit;
	color: inherit;
	margin: 0;
	padding: 0;
}

button,
select {
	text-transform: none;
}

button,
input:where([type="button"]),
input:where([type="reset"]),
input:where([type="submit"]) {
	-webkit-appearance: button;
	background-color: transparent;
	background-image: none;
}

[role="button"],
button {
	cursor: pointer;
}

:disabled {
	cursor: default;
}

img,
video {
	max-width: 100%;
	height: auto;
}

[hidden]:where(:not([hidden="until-found"])) {
	display: none;
}

/* Typography Classes */
.text-mh1 {
	font-family: 'Neue Haas Grotesk Display Pro';
	font-size: 40px;
	font-weight: 500;
	line-height: 120%;
}

.text-mh2 {
	font-family: 'Neue Haas Grotesk Display Pro';
	font-size: 35px;
	font-weight: 500;
	line-height: 120%;
}

.text-mh3 {
	font-family: 'Neue Haas Grotesk Display Pro';
	font-size: 30px;
	font-weight: 500;
	line-height: 36px;
	letter-spacing: 0.6px;
}

.text-mh4 {
	font-family: 'Neue Haas Grotesk Display Pro';
	font-size: 24px;
	font-weight: 500;
	line-height: 120%;
}

.text-b1 {
	font-family: Inter;
	font-size: 20px;
	line-height: 140%;
	letter-spacing: 0.2px;
}

.text-b2 {
	font-family: Inter;
	font-size: 18px;
	line-height: 160%;
}

.text-button {
	font-family: Inter;
	font-size: 16px;
	line-height: 150%;
}

@media (min-width: 1024px) {
	.lg\:text-h1 {
		font-family: 'Neue Haas Grotesk Display Pro';
		font-size: 95px;
		font-weight: 500;
		line-height: 100%;
	}

	.lg\:text-h2 {
		font-family: 'Neue Haas Grotesk Display Pro';
		font-size: 80px;
		font-weight: 500;
		line-height: 100%;
		letter-spacing: -1px;
	}

	.lg\:text-h3 {
		font-family: 'Neue Haas Grotesk Display Pro';
		font-size: 60px;
		font-weight: 500;
		line-height: 100%;
		letter-spacing: 0.6px;
	}

	.lg\:text-h4 {
		font-family: 'Neue Haas Grotesk Display Pro';
		font-size: 30px;
		font-weight: 500;
		line-height: 100%;
		letter-spacing: 0.3px;
	}
}

/* Layout Classes */
.container {
	margin-left: auto;
	margin-right: auto;
	display: flex;
	width: 100%;
	flex-direction: column;
	justify-content: center;
	padding-left: 1.5rem;
	padding-right: 1.5rem;
}

@media (min-width: 1024px) {
	.container {
		width: 1000px;
		padding-left: 0;
		padding-right: 0;
	}
}

@media (min-width: 1280px) {
	.container {
		width: 1240px;
	}
}

.section {
	display: flex;
	width: 100%;
	flex-direction: column;
	align-items: center;
	padding-top: 100px;
	padding-bottom: 100px;
}

@media (min-width: 1024px) {
	.section {
		padding-top: 200px;
		padding-bottom: 200px;
	}
}

/* Component Styles */
.hero {
	text-align: center;
	margin-bottom: 40px;
	background: rgba(255, 255, 255, 0.05);
	border-radius: 16px;
	padding: 30px;
	border: 1px solid rgba(255, 255, 255, 0.1);
}

.hero h1 {
	font-family: 'Neue Haas Grotesk Display Pro';
	font-size: 2.5rem;
	font-weight: 500;
	margin-bottom: 10px;
	color: #ffffff;
}

@media (min-width: 1024px) {
	.hero h1 {
		font-size: 4rem;
	}
}

.hero p {
	font-family: Inter;
	font-size: 1.1rem;
	color: rgba(255, 255, 255, 0.8);
	font-weight: 400;
}

.main-card {
	background: rgba(255, 255, 255, 0.05);
	border-radius: 16px;
	padding: 32px;
	border: 1px solid rgba(255, 255, 255, 0.1);
}

.auth-section {
	margin-bottom: 30px;
}

.login-area, .user-info {
	text-align: center;
	padding: 24px;
	background: rgba(255, 255, 255, 0.08);
	border-radius: 12px;
	border: 1px solid rgba(255, 255, 255, 0.1);
}

.user-profile {
	display: flex;
	align-items: center;
	gap: 15px;
	justify-content: center;
}

.user-avatar {
	width: 50px;
	height: 50px;
	border-radius: 50%;
	border: 2px solid rgba(255, 255, 255, 0.2);
}

.user-details h3 {
	color: #ffffff;
	margin-bottom: 5px;
	font-weight: 500;
}

.user-details p {
	color: rgba(255, 255, 255, 0.7);
	font-weight: 400;
}

.tab-navigation {
	display: flex;
	gap: 2px;
	margin-bottom: 30px;
	background: rgba(255, 255, 255, 0.08);
	border-radius: 8px;
	padding: 4px;
}

.tab-button {
	background: transparent;
	border: none;
	color: rgba(255, 255, 255, 0.7);
	padding: 12px 24px;
	cursor: pointer;
	border-radius: 6px;
	transition: all 0.2s ease;
	font-weight: 500;
	font-size: 14px;
	flex: 1;
}

.tab-button:hover {
	color: #ffffff;
	background: rgba(255, 255, 255, 0.1);
}

.tab-button.active {
	color: #ffffff;
	background: rgba(255, 255, 255, 0.15);
}

.tab-content {
	display: none;
}

.tab-content.active {
	display: block;
}

.search-box, .image-generation-box {
	margin-bottom: 30px;
}

.search-options {
	display: flex;
	gap: 12px;
	margin-bottom: 16px;
}

.search-options select {
	flex: 1;
	padding: 12px;
	background: rgba(255, 255, 255, 0.08);
	border: 1px solid rgba(255, 255, 255, 0.2);
	border-radius: 8px;
	color: #ffffff;
	font-size: 14px;
	font-family: inherit;
}

.search-options select:focus {
	outline: none;
	border-color: rgba(255, 255, 255, 0.4);
}

.search-options select option {
	background: #1a1a1a;
	color: #ffffff;
}

.advanced-options {
	display: flex;
	gap: 20px;
	margin-bottom: 16px;
	flex-wrap: wrap;
}

.checkbox-label {
	display: flex;
	align-items: center;
	gap: 8px;
	color: rgba(255, 255, 255, 0.8);
	font-size: 14px;
	cursor: pointer;
}

.checkbox-label input[type="checkbox"] {
	width: auto;
	margin: 0;
	accent-color: rgba(255, 255, 255, 0.8);
}

input, textarea {
	width: 100%;
	padding: 16px;
	background: rgba(255, 255, 255, 0.08);
	border: 1px solid rgba(255, 255, 255, 0.2);
	border-radius: 8px;
	color: #ffffff;
	font-size: 16px;
	font-family: inherit;
	margin-bottom: 16px;
	transition: all 0.2s ease;
}

input:focus, textarea:focus {
	outline: none;
	border-color: rgba(255, 255, 255, 0.4);
	background: rgba(255, 255, 255, 0.12);
}

::placeholder {
	color: rgba(255, 255, 255, 0.5);
}

button {
	width: 100%;
	padding: 16px;
	background: rgba(255, 255, 255, 0.1);
	border: 1px solid rgba(255, 255, 255, 0.2);
	border-radius: 8px;
	color: #ffffff;
	cursor: pointer;
	transition: all 0.2s ease;
	font-weight: 500;
	font-size: 16px;
	font-family: inherit;
	margin-bottom: 15px;
}

button:hover {
	background: rgba(255, 255, 255, 0.15);
	border-color: rgba(255, 255, 255, 0.3);
	transform: translateY(-1px);
}

button:active {
	transform: translateY(0);
}

button:disabled {
	opacity: 0.5;
	cursor: not-allowed;
	transform: none;
}

.results-container {
	margin-top: 30px;
}

.result-item {
	background: rgba(255, 255, 255, 0.08);
	border: 1px solid rgba(255, 255, 255, 0.1);
	border-radius: 12px;
	padding: 24px;
	margin-bottom: 16px;
	transition: all 0.2s ease;
}

.result-item:hover {
	background: rgba(255, 255, 255, 0.12);
	border-color: rgba(255, 255, 255, 0.2);
	transform: translateY(-2px);
}

.result-title {
	margin-bottom: 10px;
}

.result-title a {
	color: #ffffff;
	text-decoration: none;
	font-size: 1.1rem;
	font-weight: 500;
	transition: color 0.2s ease;
}

.result-title a:hover {
	color: rgba(255, 255, 255, 0.8);
	text-decoration: underline;
}

.result-url {
	color: rgba(255, 255, 255, 0.6);
	font-size: 0.9rem;
	font-weight: 400;
}

.result-summary {
	margin: 12px 0;
	color: rgba(255, 255, 255, 0.8);
	font-size: 0.95rem;
	line-height: 1.5;
}

.result-content {
	margin: 12px 0;
	color: rgba(255, 255, 255, 0.7);
	font-size: 0.9rem;
	line-height: 1.6;
	background: rgba(255, 255, 255, 0.05);
	padding: 12px;
	border-radius: 6px;
	border-left: 3px solid rgba(255, 255, 255, 0.2);
}

.result-highlights {
	margin: 12px 0;
}

.result-highlights h4 {
	color: rgba(255, 255, 255, 0.9);
	font-size: 0.9rem;
	margin-bottom: 8px;
}

.highlight-item {
	background: rgba(255, 255, 255, 0.05);
	border-left: 3px solid rgba(255, 255, 255, 0.3);
	padding: 8px 12px;
	margin: 6px 0;
	border-radius: 4px;
	font-size: 0.9rem;
	color: rgba(255, 255, 255, 0.8);
	font-style: italic;
}

.result-actions {
	margin-top: 15px;
	display: flex;
	gap: 10px;
}

.action-btn {
	padding: 6px 12px;
	background: rgba(255, 255, 255, 0.1);
	border: 1px solid rgba(255, 255, 255, 0.2);
	border-radius: 6px;
	color: rgba(255, 255, 255, 0.9);
	font-size: 0.8rem;
	cursor: pointer;
	transition: all 0.2s ease;
	width: auto;
	margin: 0;
}

.action-btn:hover {
	background: rgba(255, 255, 255, 0.15);
	transform: none;
}

.generated-image {
	text-align: center;
	margin-top: 20px;
}

.generated-image img {
	max-width: 100%;
	height: auto;
	border-radius: 12px;
	border: 1px solid rgba(255, 255, 255, 0.2);
}

.generated-image p {
	margin-top: 15px;
	color: rgba(255, 255, 255, 0.7);
	font-style: italic;
	font-weight: 400;
}

.image-options {
	display: grid;
	grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
	gap: 16px;
	margin-bottom: 20px;
	padding: 20px;
	background: rgba(255, 255, 255, 0.05);
	border-radius: 12px;
	border: 1px solid rgba(255, 255, 255, 0.1);
}

.option-group {
	display: flex;
	flex-direction: column;
	gap: 6px;
}

.option-group label {
	color: rgba(255, 255, 255, 0.8);
	font-size: 14px;
	font-weight: 500;
}

.option-group select,
.option-group input[type="number"] {
	margin-bottom: 0;
	padding: 8px 12px;
	font-size: 14px;
}

.checkbox-group {
	flex-direction: row;
	align-items: center;
	gap: 8px;
}

.checkbox-group label {
	margin: 0;
	flex-direction: row;
	align-items: center;
}

.login-btn {
	margin-top: 15px;
	background: rgba(0, 120, 212, 0.8);
	border-color: rgba(0, 120, 212, 0.9);
}

.login-btn:hover {
	background: rgba(0, 120, 212, 1);
	border-color: rgba(0, 120, 212, 1);
}

textarea {
	min-height: 120px;
	resize: vertical;
}

/* Scrollbar styling */
::-webkit-scrollbar {
	width: 8px;
}

::-webkit-scrollbar-track {
	background: rgba(255, 255, 255, 0.1);
	border-radius: 4px;
}

::-webkit-scrollbar-thumb {
	background: rgba(255, 255, 255, 0.3);
	border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
	background: rgba(255, 255, 255, 0.5);
}

/* Responsive design */
@media (max-width: 768px) {
	.container {
		padding: 16px;
	}

	.hero {
		padding: 24px;
		margin-bottom: 24px;
	}

	.main-card {
		padding: 24px;
	}

	.hero h1 {
		font-size: 2rem;
	}

	.user-profile {
		flex-direction: column;
		text-align: center;
	}

	.image-options {
		grid-template-columns: 1fr;
	}
}

/* Smooth animations */
@media (prefers-reduced-motion: no-preference) {
	* {
		scroll-behavior: smooth;
	}
}

/* Interactive elements */
.interactive-opacity {
	transition: opacity 0.3s ease;
}

.interactive-opacity:hover {
	opacity: 0.6;
}

/* Additional utility classes */
.flex-center {
	display: flex;
	align-items: center;
	justify-content: center;
}

.text-center {
	text-align: center;
}

.hidden {
	display: none;
}

.block {
	display: block;
}

.flex {
	display: flex;
}

.w-full {
	width: 100%;
}

.h-full {
	height: 100%;
}

.bg-transparent {
	background-color: transparent;
}

.border-none {
	border: none;
}

.outline-none {
	outline: none;
}

.transition-all {
	transition: all 0.2s ease;
}

html:
<!DOCTYPE html>
<html lang="hu">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Kollár Sándor - Intelligens Keresés és Képgenerálás</title>
  <link rel="stylesheet" href="style.css">
  <script authed="location.reload()" src=""></script>
</head>
<body>
  <div class="container">
    <div class="hero">
      <h1 class="text-mh1 lg:text-h1">Kollár Sándor</h1>
      <p class="text-b1">Intelligens keresés és képgenerálás</p>
    </div>

    <div class="main-card">
      <!-- Authentication section -->
      <div id="auth-section" class="auth-section">
        <div id="login-area" class="login-area" style="display: none;">
          <h3 class="text-mh4">Bejelentkezés szükséges</h3>
          <p class="text-b2">A funkciók használatához jelentkezz be Replit fiókodddal.</p>
          <button onclick="LoginWithReplit()" class="login-btn text-button">Bejelentkezés Replit-tel</button>
        </div>
        <div id="user-info" class="user-info" style="display: none;">
          <div class="user-profile">
            <img id="user-avatar" src="" alt="Profile" class="user-avatar">
            <div class="user-details">
              <h3 id="user-name" class="text-mh4"></h3>
              <p id="user-bio" class="text-b2"></p>
            </div>
          </div>
        </div>
      </div>

      <!-- Tab Navigation -->
      <div class="tab-navigation">
        <button id="search-tab" class="tab-button active text-button">Keresés</button>
        <button id="image-tab" class="tab-button text-button">Képgenerálás</button>
      </div>

      <!-- Search Content -->
      <div id="search-content" class="tab-content active">
        <div class="search-box">
          <input type="text" id="search-input" placeholder="Keresés..." class="text-button">
          <div class="search-options">
            <select id="search-type" class="text-button">
              <option value="auto">Automatikus</option>
              <option value="neural">Neurális keresés</option>
              <option value="keyword">Kulcsszó keresés</option>
            </select>
            <select id="search-category" class="text-button">
              <option value="">Minden kategória</option>
              <option value="news">Hírek</option>
              <option value="research">Kutatás</option>
              <option value="company">Vállalati</option>
              <option value="github">GitHub</option>
              <option value="linkedin">LinkedIn</option>
              <option value="twitter">Twitter/X</option>
            </select>
          </div>
          <div class="advanced-options">
            <label class="checkbox-label">
              <input type="checkbox" id="include-highlights"> Kiemelések
            </label>
            <label class="checkbox-label">
              <input type="checkbox" id="include-summary"> Összefoglalók
            </label>
            <label class="checkbox-label">
              <input type="checkbox" id="include-content"> Teljes tartalom
            </label>
          </div>
          <button id="search-button" class="text-button">Keresés</button>
        </div>
        <div id="search-results" class="results-container"></div>
      </div>

      <!-- Image Generation Content -->
      <div id="image-content" class="tab-content">
        <div class="image-generation-box">
          <textarea id="image-prompt" placeholder="Írj le, milyen képet szeretnél generálni..." rows="3" class="text-button"></textarea>

          <div class="image-options">
            <div class="option-group">
              <label for="aspect-ratio" class="text-button">Képarány:</label>
              <select id="aspect-ratio" class="text-button">
                <option value="1:1">1:1 (Négyzet)</option>
                <option value="16:9" selected>16:9 (Szélesvásznú)</option>
                <option value="21:9">21:9 (Ultra-széles)</option>
                <option value="3:2">3:2 (Fotó)</option>
                <option value="2:3">2:3 (Portré)</option>
                <option value="4:5">4:5 (Instagram)</option>
                <option value="5:4">5:4 (Tájkép)</option>
                <option value="3:4">3:4 (Portré klasszikus)</option>
                <option value="4:3">4:3 (Klasszikus)</option>
                <option value="9:16">9:16 (Mobil portré)</option>
                <option value="9:21">9:21 (Ultra portré)</option>
              </select>
            </div>

            <div class="option-group">
              <label for="output-format" class="text-button">Formátum:</label>
              <select id="output-format" class="text-button">
                <option value="webp">WebP (optimalizált)</option>
                <option value="jpg" selected>JPG (kompatibilis)</option>
                <option value="png">PNG (veszteségmentes)</option>
              </select>
            </div>

            <div class="option-group">
              <label for="output-quality" class="text-button">Minőség:</label>
              <select id="output-quality" class="text-button">
                <option value="80">80 (gyors)</option>
                <option value="90" selected>90 (kiváló)</option>
                <option value="95">95 (prémium)</option>
                <option value="100">100 (maximum)</option>
              </select>
            </div>

            <div class="option-group">
              <label for="safety-tolerance" class="text-button">Biztonság:</label>
              <select id="safety-tolerance" class="text-button">
                <option value="1">1 (szigorú)</option>
                <option value="2" selected>2 (normál)</option>
                <option value="3">3 (engedékeny)</option>
                <option value="4">4 (minimális)</option>
                <option value="5">5 (kikapcsolva)</option>
              </select>
            </div>

            <div class="option-group checkbox-group">
              <label class="checkbox-label">
                <input type="checkbox" id="raw-mode"> Nyers mód (professzionális)
              </label>
            </div>

            <div class="option-group">
              <label for="seed" class="text-button">Seed (reprodukálhatóság):</label>
              <input type="number" id="seed" placeholder="Véletlenszerű" min="0" max="4294967295" class="text-button">
            </div>

            <div class="option-group">
              <label for="prompt-upsampling" class="text-button">Prompt fejlesztés:</label>
              <select id="prompt-upsampling" class="text-button">
                <option value="true" selected>Igen (ajánlott)</option>
                <option value="false">Nem</option>
              </select>
            </div>
          </div>

          <button id="generate-button" class="text-button">Kép generálása</button>
          <div id="image-result"></div>
        </div>
      </div>
    </div>
  </div>

  <script>
    document.addEventListener('DOMContentLoaded', () => {
      const searchInput = document.getElementById('search-input');
      const searchButton = document.getElementById('search-button');
      const resultsContainer = document.getElementById('search-results');

      // Tab elements
      const searchTab = document.getElementById('search-tab');
      const imageTab = document.getElementById('image-tab');
      const searchContent = document.getElementById('search-content');
      const imageContent = document.getElementById('image-content');

      // Image generation elements
      const imagePrompt = document.getElementById('image-prompt');
      const generateButton = document.getElementById('generate-button');
      const imageResult = document.getElementById('image-result');

      // Tab switching
      searchTab.addEventListener('click', () => {
        searchTab.classList.add('active');
        imageTab.classList.remove('active');
        searchContent.classList.add('active');
        imageContent.classList.remove('active');
      });

      imageTab.addEventListener('click', () => {
        imageTab.classList.add('active');
        searchTab.classList.remove('active');
        imageContent.classList.add('active');
        searchContent.classList.remove('active');
      });

      searchButton.addEventListener('click', performSearch);
      searchInput.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') performSearch();
      });

      generateButton.addEventListener('click', generateImage);

      async function generateImage() {
        const prompt = imagePrompt.value.trim();
        if (!prompt) return;

        // Get all the advanced options
        const aspectRatio = document.getElementById('aspect-ratio').value;
        const outputFormat = document.getElementById('output-format').value;
        const outputQuality = parseInt(document.getElementById('output-quality').value);
        const safetyTolerance = parseInt(document.getElementById('safety-tolerance').value);
        const rawMode = document.getElementById('raw-mode').checked;
        const seed = document.getElementById('seed').value;
        const promptUpsampling = document.getElementById('prompt-upsampling').value === 'true';

        // Show loading in image result area
        imageResult.innerHTML = '<p class="text-b2">Kép generálása...</p>';

        try {
          const requestBody = {
            prompt,
            aspect_ratio: aspectRatio,
            output_format: outputFormat,
            output_quality: outputQuality,
            safety_tolerance: safetyTolerance,
            raw: rawMode,
            prompt_upsampling: promptUpsampling
          };

          // Add seed if provided
          if (seed && !isNaN(parseInt(seed))) {
            requestBody.seed = parseInt(seed);
          }

          const response = await fetch('/generate-image', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json'
            },
            body: JSON.stringify(requestBody)
          });

          const data = await response.json();

          if (data.imageUrl) {
            const seedInfo = data.seed ? ` | Seed: ${data.seed}` : '';
            imageResult.innerHTML = `
              <div class="generated-image">
                <img src="${data.imageUrl}" alt="Generált kép" />
                <p class="text-b2">Prompt: "${prompt}"</p>
                <p class="text-b2">Beállítások: ${aspectRatio} | ${outputFormat.toUpperCase()} | Minőség: ${outputQuality}${seedInfo}</p>
              </div>
            `;
          } else {
            imageResult.innerHTML = '<p class="text-b2">Nem sikerült generálni a képet.</p>';
          }
        } catch (error) {
          console.error('Error:', error);
          imageResult.innerHTML = '<p class="text-b2">Hiba történt a képgenerálás közben.</p>';
        }
      }

      async function performSearch() {
        const query = searchInput.value.trim();
        if (!query) return;

        const searchType = document.getElementById('search-type').value;
        const searchCategory = document.getElementById('search-category').value;
        const includeHighlights = document.getElementById('include-highlights').checked;
        const includeSummary = document.getElementById('include-summary').checked;
        const includeContent = document.getElementById('include-content').checked;

        resultsContainer.innerHTML = '<p class="text-b2">Keresés...</p>';

        try {
          let endpoint = '/search';
          let requestBody = { 
            query, 
            filters: { type: searchType }
          };

          // Use category-specific search if category is selected
          if (searchCategory) {
            endpoint = '/search-category';
            requestBody = { query, category: searchCategory };
          } else if (includeHighlights || includeSummary || includeContent) {
            // Use enhanced search for advanced features
            endpoint = '/search-enhanced';
            requestBody = {
              query,
              filters: { 
                type: searchType,
                text: true  // Always request text for enhanced features
              },
              highlights: includeHighlights,
              summary: includeSummary
            };
          }

          const response = await fetch(endpoint, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json'
            },
            body: JSON.stringify(requestBody)
          });

          const data = await response.json();

          console.log('Search response data:', data);
          if (data.results && data.results.length > 0) {
            displayResults(data.results, includeContent);
          } else {
            resultsContainer.innerHTML = '<p class="text-b2">Nem találhatók eredmények.</p>';
          }
        } catch (error) {
          console.error('Error:', error);
          resultsContainer.innerHTML = '<p class="text-b2">Hiba történt a keresés közben.</p>';
        }
      }

      function displayResults(results, showContent = false) {
        console.log('Displaying results:', results);
        console.log('Show content:', showContent);
        resultsContainer.innerHTML = '';

        results.forEach((result, index) => {
          console.log(`Result ${index}:`, result);
          const resultItem = document.createElement('div');
          resultItem.className = 'result-item';

          const title = document.createElement('h3');
          title.className = 'result-title';

          const link = document.createElement('a');
          link.href = result.url;
          link.textContent = result.title;
          link.target = '_blank';
          link.className = 'text-mh4';

          title.appendChild(link);

          const url = document.createElement('p');
          url.className = 'result-url text-b2';
          url.textContent = result.url;

          resultItem.appendChild(title);
          resultItem.appendChild(url);

          // Add summary if available
          if (result.summary) {
            const summary = document.createElement('div');
            summary.className = 'result-summary text-b2';
            summary.innerHTML = `<strong>Összefoglaló:</strong> ${result.summary}`;
            resultItem.appendChild(summary);
            console.log('Added summary:', result.summary);
          } else {
            console.log('No summary for result:', result.title);
          }

          // Add full text content if available and requested
          if (result.text && showContent) {
            const content = document.createElement('div');
            content.className = 'result-content text-b2';
            content.innerHTML = `<strong>Teljes tartalom:</strong><br>${result.text.substring(0, 1000)}${result.text.length > 1000 ? '...' : ''}`;
            resultItem.appendChild(content);
          }

          // Add highlights if available
          if (result.highlights && result.highlights.length > 0) {
            const highlightsDiv = document.createElement('div');
            highlightsDiv.className = 'result-highlights';

            const highlightsTitle = document.createElement('h4');
            highlightsTitle.textContent = 'Kiemelések:';
            highlightsTitle.className = 'text-button';
            highlightsDiv.appendChild(highlightsTitle);

            result.highlights.forEach(highlight => {
              const highlightItem = document.createElement('div');
              highlightItem.className = 'highlight-item text-b2';
              highlightItem.innerHTML = highlight;
              highlightsDiv.appendChild(highlightItem);
            });

            resultItem.appendChild(highlightsDiv);
          }

          // Add action buttons
          const actionsDiv = document.createElement('div');
          actionsDiv.className = 'result-actions';

          const similarBtn = document.createElement('button');
          similarBtn.className = 'action-btn text-button';
          similarBtn.textContent = 'Hasonló cikkek';
          similarBtn.onclick = () => findSimilar(result.url);

          const contentBtn = document.createElement('button');
          contentBtn.className = 'action-btn text-button';
          contentBtn.textContent = 'Tartalom letöltése';
          contentBtn.onclick = () => getContent(result.id);

          actionsDiv.appendChild(similarBtn);
          actionsDiv.appendChild(contentBtn);
          resultItem.appendChild(actionsDiv);

          resultsContainer.appendChild(resultItem);
        });
      }

      async function findSimilar(url) {
        resultsContainer.innerHTML = '<p class="text-b2">Hasonló cikkek keresése...</p>';

        try {
          const response = await fetch('/similar', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json'
            },
            body: JSON.stringify({ url })
          });

          const data = await response.json();

          if (data.results && data.results.length > 0) {
            displayResults(data.results);
          } else {
            resultsContainer.innerHTML = '<p class="text-b2">Nem találhatók hasonló cikkek.</p>';
          }
        } catch (error) {
          console.error('Error:', error);
          resultsContainer.innerHTML = '<p class="text-b2">Hiba történt a hasonló cikkek keresése közben.</p>';
        }
      }

      async function getContent(id) {
        if (!id) {
          alert('Nincs elérhető tartalom ID');
          return;
        }

        try {
          const response = await fetch('/contents', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json'
            },
            body: JSON.stringify({ ids: [id] })
          });

          const data = await response.json();

          if (data.results && data.results.length > 0) {
            const content = data.results[0];

            // Create a modal or new section to display content
            const modal = document.createElement('div');
            modal.style.cssText = `
              position: fixed;
              top: 0;
              left: 0;
              width: 100%;
              height: 100%;
              background: rgba(0, 0, 0, 0.9);
              z-index: 1000;
              display: flex;
              justify-content: center;
              align-items: center;
              padding: 20px;
            `;

            const modalContent = document.createElement('div');
            modalContent.style.cssText = `
              background: rgba(255, 255, 255, 0.08);
              border-radius: 16px;
              padding: 32px;
              max-width: 800px;
              max-height: 80%;
              overflow-y: auto;
              border: 1px solid rgba(255, 255, 255, 0.2);
            `;

            modalContent.innerHTML = `
              <h2 class="text-mh2" style="color: white; margin-bottom: 20px;">${content.title}</h2>
              <p class="text-b2" style="color: rgba(255,255,255,0.7); margin-bottom: 20px;">${content.url}</p>
              <div class="text-b2" style="color: rgba(255,255,255,0.9); line-height: 1.6;">${content.text || 'Nincs elérhető tartalom'}</div>
              <button onclick="this.parentElement.parentElement.remove()" class="text-button" style="margin-top: 20px; padding: 10px 20px; background: rgba(255,255,255,0.15); border: 1px solid rgba(255,255,255,0.3); border-radius: 8px; color: white; cursor: pointer;">Bezárás</button>
            `;

            modal.appendChild(modalContent);
            document.body.appendChild(modal);

            modal.onclick = (e) => {
              if (e.target === modal) {
                modal.remove();
              }
            };
          } else {
            alert('Nem sikerült letölteni a tartalmat');
          }
        } catch (error) {
          console.error('Error:', error);
          alert('Hiba történt a tartalom letöltése közben');
        }
      }
    });
  </script>
</body>
</html>


js: // Simple functionality only
document.addEventListener('DOMContentLoaded', function() {
  const searchTab = document.getElementById('search-tab');
  const imageTab = document.getElementById('image-tab');
  const searchContent = document.getElementById('search-content');
  const imageContent = document.getElementById('image-content');

  searchTab.addEventListener('click', () => {
    searchTab.classList.add('active');
    imageTab.classList.remove('active');
    searchContent.classList.add('active');
    imageContent.classList.remove('active');
  });

  imageTab.addEventListener('click', () => {
    imageTab.classList.add('active');
    searchTab.classList.remove('active');
    imageContent.classList.add('active');
    searchContent.classList.remove('active');
  });

  const searchButton = document.getElementById('search-button');
  const searchInput = document.getElementById('search-input');
  const resultsContainer = document.getElementById('search-results');

  searchButton.addEventListener('click', performSearch);
  searchInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') performSearch();
  });

  async function performSearch() {
    const query = searchInput.value.trim();
    if (!query) return;

    try {
      searchButton.textContent = 'Keresés...';
      searchButton.disabled = true;

      const response = await fetch('/search', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ query })
      });

      const data = await response.json();
      displayResults(data.results);
    } catch (error) {
      console.error('Keresési hiba:', error);
      resultsContainer.innerHTML = '<p>Keresési hiba történt</p>';
    } finally {
      searchButton.textContent = 'Keresés';
      searchButton.disabled = false;
    }
  }

  function displayResults(results) {
    if (!results || results.length === 0) {
      resultsContainer.innerHTML = '<p>Nincs találat</p>';
      return;
    }

    const resultsHtml = results.map(result => `
      <div class="result-item">
        <h3>${result.title}</h3>
        <p class="result-url">${result.url}</p>
      </div>
    `).join('');

    resultsContainer.innerHTML = resultsHtml;
  }

  const generateButton = document.getElementById('generate-button');
  const imagePrompt = document.getElementById('image-prompt');
  const imageResult = document.getElementById('image-result');

  if (generateButton) {
    generateButton.addEventListener('click', generateImage);
  }

  async function generateImage() {
    const prompt = imagePrompt.value.trim();
    if (!prompt) return;

    try {
      generateButton.textContent = 'Generálás...';
      generateButton.disabled = true;

      const response = await fetch('/generate-image', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ prompt })
      });

      const data = await response.json();

      if (data.imageUrl) {
        imageResult.innerHTML = `<img src="${data.imageUrl}" alt="Generált kép" style="max-width: 100%; height: auto; border-radius: 6px;">`;
      } else {
        imageResult.innerHTML = '<p>Képgenerálás sikertelen</p>';
      }
    } catch (error) {
      console.error('Képgenerálási hiba:', error);
      imageResult.innerHTML = '<p>Képgenerálási hiba történt</p>';
    } finally {
      generateButton.textContent = 'Kép generálása';
      generateButton.disabled = false;
    }
  }

  function checkAuthStatus() {
    fetch('/.replit/auth/userinfo')
      .then(response => {
        if (response.ok) {
          return response.json();
        } else {
          throw new Error('Not authenticated');
        }
      })
      .then(data => {
        console.log('Authenticated as:', data);
      })
      .catch(error => {
        console.error('Authentication check failed:', error);
      });
  }
});


